ModelProject.all.find(p=>p.name==="root_rot_armor_original").select();
const config=Project.dungeons_material_source;
const source=Texture.all.find(t=>t.uuid===config.albedo_uuid).getOwnMaterial();
const renderer=Preview.selected.renderer;
const target=new THREE.WebGLRenderTarget(64,64,{type:THREE.FloatType,minFilter:THREE.NearestFilter,magFilter:THREE.NearestFilter,depthBuffer:false,stencilBuffer:false});
const uniforms=Object.assign({},source.uniforms,{sourcePreviewMode:{value:2},sourceEmissionEnabled:{value:1}});
