const geometry=new THREE.PlaneGeometry(2,2);
const scene=new THREE.Scene();scene.add(new THREE.Mesh(geometry,material));
const camera=new THREE.Camera();
const previous=renderer.getRenderTarget();const clear=renderer.getClearColor(new THREE.Color());const alpha=renderer.getClearAlpha();
const pixels=new Float32Array(64*64*4);
try{renderer.setRenderTarget(target);renderer.setClearColor(0,0);renderer.clear();renderer.render(scene,camera);renderer.readRenderTargetPixels(target,0,0,64,64,pixels);}
finally{renderer.setRenderTarget(previous);renderer.setClearColor(clear,alpha);material.dispose();geometry.dispose();target.dispose();}
return {project:Project.name,parameters:config.parameters,width:64,height:64,encoding:"Float32 RGBA, framebuffer bottom-up; raw linear HDR before preview tonemapping",pixels:Array.from(pixels)};
})()

