    for(const raw of d.meshes){
      const m=Mesh.all.find(m=>m.uuid===raw.uuid);
      if(!m||Object.keys(m.vertices).length!==Object.keys(raw.vertices).length)throw Error("Mesh mismatch");
      for(const [v,position]of Object.entries(raw.vertices))m.vertices[v]=position.slice();
    }
    for(const raw of d.bones){
      const b=ArmatureBone.all.find(b=>b.uuid===raw.uuid);
      if(!b)throw Error("Bone mismatch");
      b.origin=raw.origin.slice();b.rotation=raw.rotation.slice();
    }
    Canvas.updateAll();
    return {meshes:Mesh.all.length,bones:ArmatureBone.all.length,source_status:d.status,layout:d.pieces.map(p=>({label:p.label,hinge:p.hinge_world,scale:p.uniform_scale}))};
    })()

