      let count=0;
      for(const track of raw.tracks){
        const b=ArmatureBone.all.find(b=>b.name===track.bone);
        if(!b)throw Error("Missing wing bone");
        const animator=a.getBoneAnimator(b);
        if(animator.rotation.length)throw Error("Existing wing keys");
        for(const k of track.keyframes){
          const key=animator.addKeyframe(k);
          for(const axis of ["x","y","z"])key.data_points[0][axis]=Number(k.data_points[0][axis]).toFixed(15);
          count++;
        }
      }
      records.push({name:a.name,wing_keys:count});
    }
    Animation.all.forEach(a=>a.playing=false);
    const a=Animation.all.find(a=>a.name==="animation.idle");a.select();a.playing=true;Timeline.time=0;Animator.preview();
    return {clips:records,total:records.reduce((s,r)=>s+r.wing_keys,0)};
    })()

