(()=>{const p=ModelProject.all.find(p=>p.uuid==="a2b17270-75c4-e5ef-cf18-107d4eaf2b7f");if(!p)throw Error("Missing six-wing working project");p.select();
    Modes.options.edit.select();unselectAll();Canvas.updateAll();
    const v=new Preview({id:"lucifer_cuboid_review_render",offscreen:true});v.loadAnglePreset({position:[0,24,-130],target:[0,24,9],projection:"orthographic"});
    v.resize(1100,825);v.renderer.setPixelRatio(1);v.camOrtho.zoom=(v.camOrtho.right-v.camOrtho.left)/88;v.camOrtho.updateProjectionMatrix();v.camera.lookAt(v.controls.target);
    const handlers=ArmatureBone.all.map(b=>({b,own:Object.prototype.hasOwnProperty.call(b,"getTypeBehavior"),original:b.getTypeBehavior}));
    const visuals=[];
    for(const h of handlers){
      h.b.getTypeBehavior=function(key){return key==="hide_in_screenshot"?false:h.original.call(this,key)};
      for(const child of h.b.scene_object.children)if(child.type==="armature_bone"){visuals.push([child,child.visible]);child.visible=false;}
    }
    try{
      let picture;Screencam.screenshotPreview(v,{crop:true,width:1000,height:750},url=>picture=url);
      return {picture,width:v.width,height:v.height,zoom:v.camOrtho.zoom,material:LuciferOriginalMaterial.status(),method:"Native screenshot with bone visual gizmos hidden separately; bone containers retain visible Cube descendants."};
    }finally{
      for(const [visual,visible]of visuals)visual.visible=visible;
      for(const h of handlers){if(h.own)h.b.getTypeBehavior=h.original;else delete h.b.getTypeBehavior;}
      v.delete();
    }
    })()

